#[derive(Default)]
pub struct ObservationBatch {
    pub facts: Vec<ObservationFact>,
    pub gaps: Vec<ObservationGap>,
    /// Human-only causes for the [`ObservationGap::IntervalUnknown`]
    /// instances in [`Self::gaps`] (v0.6.0 W3-shard), aligned in
    /// order: `interval_causes[i]` explains the i-th interval gap.
    /// Recorded only through `gap_interval_unknown` (the producing
    /// site names its cause); never serialized — JSON keeps the
    /// bare gaps verbatim.
    pub interval_causes: Vec<IntervalCause>,
    /// Shaped backing-refusal strings drained from the acquisition
    /// budget (R06 vocabulary, caller-rendered). The session merges
    /// these into its attach diagnostics at projection.
    pub refusals: Vec<String>,
    pub learned_sites: Vec<VerifiedSiteCandidate>,
    pub static_candidates: Vec<VerifiedStaticCandidate>,
    pub api_activity: Vec<ProcessApiActivity>,
    /// Scopes with a SUCCESSFUL terminal count read (NEW-P1): one
    /// `(pid, starttime)` per incarnation with at least one
    /// successful scoped read. Failed reads and merge-padded rows
    /// never land here — the request-fold plane gates on this set
    /// (absent scope + zero entries = Unknown, never an observed
    /// zero). Never serialized.
    pub terminal_scopes_observed: BTreeSet<(u32, u64)>,
    /// Internal provider reacquisition marker for stronger inventory authority.
    /// Count may bridge only after independently revalidating retained custody;
    /// this is not a claim that process or backing code changed identity.
    pub refreshed_processes: Vec<u32>,
    /// 6A exec witnesses (session-detected exe-stamp flips, §1.4): pids
    /// whose image epoch sealed this reconcile. The coordinator seals
    /// the segment and re-admits the post-exec image as a fresh
    /// candidate; the session never re-adds these pids itself
    /// (`exec_sealed`).
    pub exec_witnesses: Vec<u32>,
    /// R7-1 deferred-exec DETECTION signal: pids whose exec was
    /// detected but whose retire deferred this batch (fresh
    /// detections only — witnesses still ride retry completion
    /// via `exec_witnesses`). The focused layer fences its count
    /// plane IMMEDIATELY on this signal, using the preceding-clean
    /// edge, and freezes its clean instant while the session holds
    /// the fence (`exec_fence_held`) — a witness-free drain must
    /// not advance the clean instant past a deferred exec.
    pub exec_deferred: Vec<u32>,
    /// 6A additive module refreshes (§1.2 late modules): pids whose
    /// binding refreshed over added-only rows this reconcile
    /// (distinct from `refreshed_processes`, which also covers
    /// authority upgrades). The coordinator emits the
    /// `additive_module_refresh` transition detail.
    pub additive_refreshes: Vec<u32>,
}
/// One cumulative final API ledger, scoped to an observed incarnation.
#[derive(Clone)]
pub struct ProcessApiActivity {
    pub pid: u32,
    pub starttime: u64,
    pub row: crate::api_activity::ApiActivityRow,
}
impl ObservationBatch {
    fn gap(&mut self, g: ObservationGap) {
        if !self.gaps.contains(&g) {
            self.gaps.push(g)
        }
    }
    /// Record an interval gap WITH its producing-site cause (the
    /// only way an [`ObservationGap::IntervalUnknown`] enters a
    /// batch): the cause pushes iff the gap is newly pushed, so
    /// [`Self::interval_causes`] stays aligned with the interval
    /// gaps in order. Dedup keeps the first cause — the surviving
    /// gap is one instance in JSON too, so the human line never
    /// claims more than the machine record.
    fn gap_interval_unknown(&mut self, cause: IntervalCause) {
        if !self.gaps.contains(&ObservationGap::IntervalUnknown) {
            self.gaps.push(ObservationGap::IntervalUnknown);
            self.interval_causes.push(cause);
        }
    }
    /// Record an assembly error as its gap, attaching the join-miss
    /// cause when the error is an interval gap (every
    /// [`super::assembly::Sequences`] interval error is a window
    /// that failed to join; other gaps carry no cause).
    fn gap_from_assembly(&mut self, g: ObservationGap) {
        if g == ObservationGap::IntervalUnknown {
            self.gap_interval_unknown(IntervalCause::JoinMiss);
        } else {
            self.gap(g);
        }
    }
    /// Chain an earlier-consumed batch BEHIND this one (the
    /// retire-carry path: this carry is older, the argument was
    /// consumed later). Facts and signal vectors append in
    /// consumption order; gaps fold through the deduping `gap`
    /// (set semantics preserved — chaining equals consuming both
    /// in one batch).
    fn append_batch(&mut self, other: ObservationBatch) {
        self.facts.extend(other.facts);
        let mut causes = other.interval_causes.into_iter();
        for g in other.gaps {
            if g == ObservationGap::IntervalUnknown {
                // The aligned cause transfers iff the gap is newly
                // folded; a cause without its gap is dropped (never
                // rendered — the human line must not outclaim JSON).
                if let Some(cause) = causes.next() {
                    self.gap_interval_unknown(cause);
                } else {
                    self.gap(g);
                }
            } else {
                self.gap(g);
            }
        }
        self.refusals.extend(other.refusals);
        self.learned_sites.extend(other.learned_sites);
        self.static_candidates.extend(other.static_candidates);
        self.api_activity.extend(other.api_activity);
        self.terminal_scopes_observed
            .extend(other.terminal_scopes_observed);
        self.refreshed_processes.extend(other.refreshed_processes);
        self.exec_witnesses.extend(other.exec_witnesses);
        self.exec_deferred.extend(other.exec_deferred);
        self.additive_refreshes.extend(other.additive_refreshes);
    }
}
