    #[test]
    fn final_cut_mixed_sources_require_each_attachments_own_terminal_authority() {
        let _fixtures = MAPPED_FIXTURES.lock().unwrap_or_else(|e| e.into_inner());
        for case in ["live", "terminal", "permanent", "nonterminal-unavailable"] {
            let mut fixture = reconcile_fixture(true);
            let pid = fixture.child.pid();
            let target = fixture.targets.get_mut(&pid).unwrap();
            let site = target
                .process
                .resolve_api(wire::api(c::PUBLIC_UNQUERY).unwrap())
                .remove(0)
                .site;
            assert!(!site.is_startup());
            let (link, mut peer) = std::os::unix::net::UnixStream::pair().unwrap();
            peer.set_nonblocking(true).unwrap();
            target.attachments.push(Attachment {
                object: object_id(&site),
                site,
                cookie: 82,
                api: c::PUBLIC_UNQUERY,
                armed_ns: None,
                links: vec![link.into()],
                generation: 19,
                advertisers: Vec::new(),
                original: None,
                historical: false,
            });
            if case == "permanent" {
                target
                    .process
                    .remember_refusal(ObservationGap::ObjectChanged);
            }
            if case == "nonterminal-unavailable" {
                objects::fixture_support::lose_mapped_process_directory(&mut target.process);
                assert_eq!(
                    target.process.revalidate_fresh(),
                    Err(ObservationGap::ProcessUnavailable)
                );
            }
            if matches!(case, "terminal" | "permanent") {
                fixture.child.finish_observation().unwrap();
            }
            let mut terminal = BTreeSet::new();
            let refused = final_source_refusals(
                &fixture.targets,
                &fixture.startup,
                &mut ObservationBatch::default(),
                Instant::now() + Duration::from_secs(2),
                &mut terminal,
            );
            let record = |cookie, api| c::Record {
                pid,
                cookie,
                api,
                generation: 19,
                ..Default::default()
            };
            let original = final_record_binding(
                &fixture.targets,
                &fixture.startup,
                &refused,
                &terminal,
                &record(81, c::PUBLIC_QUERY),
            );
            let mapped = final_record_binding(
                &fixture.targets,
                &fixture.startup,
                &refused,
                &terminal,
                &record(82, c::PUBLIC_UNQUERY),
            );
            if case == "live" {
                assert!(original.unwrap().unwrap().process.is_some());
                assert!(mapped.unwrap().unwrap().process.is_some());
            } else if case == "terminal" {
                assert!(
                    mapped.is_err(),
                    "terminal PID fallback admitted a mapped-only cookie"
                );
                assert!(
                    original.unwrap().unwrap().process.is_none(),
                    "terminal original retained live relocation authority"
                );
            } else {
                assert!(original.is_err());
                assert!(mapped.is_err());
            }
            use std::io::Read;
            assert_eq!(fixture.targets[&pid].attachments.len(), 2);
            assert_eq!(
                fixture.link_peer.read(&mut [0]).unwrap_err().kind(),
                std::io::ErrorKind::WouldBlock
            );
            assert_eq!(
                peer.read(&mut [0]).unwrap_err().kind(),
                std::io::ErrorKind::WouldBlock
            );
        }
    }
    #[test]
    fn terminal_custody_predicate_matches_per_cookie_binding() {
        // NEW-8-OPEN + NEW-17 fix5 pin (host, real sites): one
        // attachment's terminal custody is its OWN validated
        // original — the same predicate `final_record_binding`
        // enforces per cookie on the terminal path (a sibling's
        // original cannot help). A startup attachment carries
        // custody (its site IS the original); a mapped-only
        // attachment carries none (no original — the binding
        // refuses its records). The seal rule unions the
        // custody-less fetch APIs into its gap set (behavior
        // pinned through production attach in the guest NEW-17
        // leg). Custody ignores the API id (the seal filters to
        // fetch), so the fixture's query/unquery pair stands in.
        let _fixtures = MAPPED_FIXTURES.lock().unwrap_or_else(|e| e.into_inner());
        let mut fixture = reconcile_fixture(true);
        let pid = fixture.child.pid();
        let target = fixture.targets.get_mut(&pid).unwrap();
        let site = target
            .process
            .resolve_api(wire::api(c::PUBLIC_UNQUERY).unwrap())
            .remove(0)
            .site;
        assert!(!site.is_startup());
        let (link, _peer) = std::os::unix::net::UnixStream::pair().unwrap();
        target.attachments.push(Attachment {
            object: object_id(&site),
            site,
            cookie: 82,
            api: c::PUBLIC_UNQUERY,
            armed_ns: None,
            links: vec![link.into()],
            generation: 19,
            advertisers: Vec::new(),
            original: None,
            historical: false,
        });
        // Seal-time state is post-exit: reap the child so custody
        // is evaluated through terminal queued-record
        // revalidation.
        fixture.child.finish_observation().unwrap();
        let target = fixture.targets.get(&pid).unwrap();
        let startup = target
            .attachments
            .iter()
            .find(|a| a.cookie == 81)
            .expect("startup attachment");
        let mapped = target
            .attachments
            .iter()
            .find(|a| a.cookie == 82)
            .expect("mapped attachment");
        assert!(
            terminal_custody(startup),
            "a startup attachment carries terminal custody"
        );
        assert!(
            !terminal_custody(mapped),
            "a mapped-only attachment carries no terminal custody"
        );
    }
