    /// NEW-32 fix8 helper: forge one fetch ATTEMPT record image
    /// bound to a real attachment (mirrors the fix4 `new7_fetch_bytes`
    /// shape; outcome 0 — ATTEMPT requires a zero outcome at
    /// decode). Pins feed these through production
    /// `decode_transport` + `consume`, so the queued facts are
    /// production-assembled and bound, like N7a's.
    fn new32_edge_bytes(
        pid: u32,
        cookie: u64,
        api: u32,
        generation: u64,
        invocation: u64,
        mono_ns: u64,
        start: u64,
    ) -> Vec<u8> {
        use super::wire::contract as c;
        let mut b = vec![0u8; c::EVENT_SIZE];
        for (at, v) in [
            (0, c::VERSION),
            (4, c::ATTEMPT),
            (8, c::EVENT_SIZE as u32),
            (12, api),
            (16, pid),
            (20, pid),
        ] {
            b[at..at + 4].copy_from_slice(&v.to_le_bytes());
        }
        for (at, v) in [
            (24, cookie),
            (32, generation),
            (40, mono_ns),
            (48, invocation),
        ] {
            b[at..at + 8].copy_from_slice(&v.to_le_bytes());
        }
        b[96..104].copy_from_slice(&start.to_le_bytes());
        b
    }
    /// NEW-32 fix8 pin (guest, real learned-role conflict): with
    /// two genuinely armed fetch-10 sites plus a second armed
    /// fetch surface (id 11), a REAL role conflict (the production
    /// `attach_learned` observing an already-roled fetch site
    /// under a second API — genuine `Ok(false)`, nothing
    /// fabricated) disarms one fetch site while its same-API
    /// sibling survives armed. The conflict must mark EVERY
    /// disarmed surface (the conflicted API and each disarmed
    /// attachment's API), must preserve queued facts from
    /// unrelated surfaces (production-assembled, bound to real
    /// attachments), and must void the surviving sibling's silence
    /// wherever fetch evidence was discarded. (A full wire-level
    /// INIT collision is not deterministic; the conflict DECISION
    /// here is genuine production roles state, and the
    /// filter/mark/seal below it are all production. Query-8
    /// ATTEMPTs do not assemble to facts — the RED trip proved
    /// the premise — so the unrelated edge is fetch-11, which
    /// assembles like any fetch surface.)
    #[test]
    #[ignore = "requires privileged BPF and fresh observation object"]
    fn learned_role_conflict_marks_surfaces_keeps_unrelated_edges() {
        use crate::capture::{ClockPort as _, LiveClock};
        use std::time::{Duration, Instant};
        let _fixtures = MAPPED_FIXTURES.lock().unwrap_or_else(|e| e.into_inner());
        let fixture = two_cipher_exporter_fixture();
        let pid = fixture._child.pid();
        let records = crate::inventory::snapshot(&crate::inventory::SnapshotOptions {
            pids: vec![pid],
            ..Default::default()
        })
        .processes;
        assert_eq!(records.len(), 1, "the child is inventoried");
        let starttime = records[0].starttime;
        let mut s = staged_production_session();
        let held = (&fixture._child, &fixture._mappings, &fixture._forwarders);
        s.process_override.borrow_mut().insert(pid, fixture.process);
        let setup = s.reconcile_records(&records);
        assert!(
            s.target_ready(pid, starttime),
            "premise: production attach completes: {:?}",
            setup.gaps
        );
        let fetch_cookies: Vec<(u64, u64)> = s
            .targets
            .get(&pid)
            .expect("target present")
            .attachments
            .iter()
            .filter(|a| a.api == 10)
            .map(|a| (a.cookie, a.generation))
            .collect();
        assert_eq!(
            fetch_cookies.len(),
            2,
            "premise: two fetch-10 sites genuinely armed"
        );
        for a in s
            .targets
            .get(&pid)
            .expect("target present")
            .attachments
            .iter()
            .filter(|a| a.api == 10)
        {
            assert_eq!(a.links.len(), 2, "premise: genuine link pair");
            assert!(a.armed_ns.is_some(), "premise: stamped arm");
        }
        let (other_cookie, other_generation) = s
            .targets
            .get(&pid)
            .expect("target present")
            .attachments
            .iter()
            .find(|a| a.api == 11)
            .map(|a| (a.cookie, a.generation))
            .expect("premise: the second fetch surface arms");
        for _ in 0..3 {
            s.drain(Instant::now() + Duration::from_millis(200));
        }
        let start = LiveClock.monotonic_ns();
        s.set_api_window(start, start.saturating_add(60_000_000_000))
            .expect("window programs");
        let _ = s.drain(Instant::now() + Duration::from_secs(5));
        assert!(
            s.armed_fetch_ids(pid, starttime).contains(&10),
            "premise: the seal covers fetch-10 pre-conflict: {:?}",
            s.armed_fetch_ids(pid, starttime)
        );
        // Queue one conflicted-surface fact (fetch-10, bound to
        // the first site) and one unrelated fact (fetch-11)
        // through production decode + consume.
        let mut batch = super::ObservationBatch::default();
        let mono = LiveClock.monotonic_ns();
        for (i, (cookie, api, generation)) in [
            (fetch_cookies[0].0, 10u32, fetch_cookies[0].1),
            (other_cookie, 11u32, other_generation),
        ]
        .into_iter()
        .enumerate()
        {
            let event = super::wire::decode_transport(&new32_edge_bytes(
                pid,
                cookie,
                api,
                generation,
                (i + 1) as u64,
                mono + i as u64,
                starttime,
            ))
            .expect("edge bytes decode");
            s.consume(event, &mut batch);
        }
        assert_eq!(
            batch.facts.len(),
            2,
            "premise: both facts queue (gaps={:?})",
            batch.gaps
        );
        // The REAL conflict: observe the first fetch site under a
        // second API through the production learned path.
        let site = s
            .targets
            .get(&pid)
            .expect("target present")
            .attachments
            .iter()
            .find(|a| a.cookie == fetch_cookies[0].0)
            .expect("first fetch attachment present")
            .site
            .clone();
        s.attach_learned(pid, 8, site, Vec::new(), &mut batch);
        assert!(
            batch.gaps.contains(&ObservationGap::AmbiguousSite),
            "premise: the conflict really fired: {:?}",
            batch.gaps
        );
        // Every disarmed surface is marked (the conflicted API 8
        // and the disarmed attachment's API 10).
        let gaps = &s.targets.get(&pid).expect("target present").site_gap_apis;
        assert!(
            gaps.contains(&8) && gaps.contains(&10),
            "every disarmed surface is marked: {gaps:?}"
        );
        // The first fetch site disarmed; its same-API sibling
        // survives armed.
        let survivors: Vec<_> = s
            .targets
            .get(&pid)
            .expect("target present")
            .attachments
            .iter()
            .filter(|a| a.api == 10)
            .collect();
        assert_eq!(
            survivors.len(),
            1,
            "one fetch site disarms, its sibling survives"
        );
        assert_eq!(survivors[0].cookie, fetch_cookies[1].0);
        assert_eq!(survivors[0].links.len(), 2, "the survivor stays genuine");
        assert!(
            survivors[0].armed_ns.is_some(),
            "the survivor stays stamped"
        );
        // Unrelated verified edges are preserved; the discarded
        // surface's edges are gone.
        assert_eq!(
            batch.facts.len(),
            1,
            "only the conflicted surface's facts drop: {:?}",
            batch.facts.iter().map(|f| f.api).collect::<Vec<_>>()
        );
        assert_eq!(
            batch.facts[0].api,
            wire::api(11).expect("cipher id"),
            "the unrelated fetch edge is preserved"
        );
        // ... and the surviving sibling certifies nothing (its
        // surface's silence is void wherever evidence discarded).
        assert!(
            !s.armed_fetch_ids(pid, starttime).contains(&10),
            "the surviving sibling seals nothing: {:?}",
            s.armed_fetch_ids(pid, starttime)
        );
        let _ = held;
        eprintln!("new32: conflict_marked=true unrelated_kept=true sibling_voided=true");
    }
    #[test]
    fn final_cut_validation_retains_terminal_owners_and_permanent_refusals() {
        let _fixtures = MAPPED_FIXTURES.lock().unwrap_or_else(|e| e.into_inner());
        for poisoned in [false, true] {
            let mut fixture = reconcile_fixture(true);
            let pid = fixture.child.pid();
            if poisoned {
                fixture.targets[&pid]
                    .process
                    .remember_refusal(ObservationGap::ObjectChanged);
            }
            fixture.child.finish_observation().unwrap();
            let mut batch = ObservationBatch::default();
            let refused = final_source_refusals(
                &fixture.targets,
                &fixture.startup,
                &mut batch,
                Instant::now() + Duration::from_secs(2),
                &mut BTreeSet::new(),
            );
            assert_eq!(
                refused.get(&pid).copied(),
                poisoned.then_some(ObservationGap::ObjectChanged)
            );
            // Validation must not close links or erase binding owners, including
            // rejected sources: disposal belongs after bounded decode/seal.
            assert_eq!(fixture.targets[&pid].attachments.len(), 1);
            use std::io::Read;
            assert_eq!(
                fixture.link_peer.read(&mut [0]).unwrap_err().kind(),
                std::io::ErrorKind::WouldBlock
            );
            let r = c::Record {
                pid,
                cookie: 81,
                api: c::PUBLIC_QUERY,
                generation: 19,
                ..Default::default()
            };
            assert!(
                record_binding(&fixture.targets, &fixture.startup, &r)
                    .unwrap()
                    .is_some()
            );
        }
    }
    #[test]
    fn terminal_reconcile_before_drain_preserves_startup_and_adopted_query_owners() {
        let _fixtures = MAPPED_FIXTURES.lock().unwrap_or_else(|e| e.into_inner());
        for stage in ["startup", "adopted", "partial"] {
            let adopted = stage != "startup";
            let mut fixture = reconcile_fixture(adopted);
            let pid = fixture.child.pid();
            if stage == "partial" {
                // First construction has moved the physical owner into Target,
                // but adoption's initial validation can fail before replacement.
                let attachment = &mut fixture.targets.get_mut(&pid).unwrap().attachments[0];
                attachment.site = attachment.original.take().unwrap();
            }
            let mut r = c::Record {
                version: c::VERSION,
                size: c::EVENT_SIZE as u32,
                kind: c::ALGORITHM_BEGIN,
                pid,
                tid: pid,
                cookie: 81,
                generation: 19,
                invocation: 7,
                api: c::PUBLIC_QUERY,
                operation: 1,
                outcome: 1,
                cacheability: 1,
                start_time_ns: 0x5A44,
                ..Default::default()
            };
            let decode = |r: &c::Record| {
                wire::decode_transport(unsafe {
                    std::slice::from_raw_parts((r as *const c::Record).cast(), c::EVENT_SIZE)
                })
                .unwrap()
            };
            let identity = record_binding(&fixture.targets, &fixture.startup, &r)
                .unwrap()
                .unwrap();
            let hash = identity.attachment.site.object_hash().clone();
            let object = identity.attachment.object;
            let file_fd = identity
                .attachment
                .original
                .as_ref()
                .unwrap_or(&identity.attachment.site)
                .attachment_fd()
                .as_raw_fd();
            let link_fd = identity.attachment.links[0].as_raw_fd();
            let mut aliases = super::super::assembly::Sequences::default();
            let mut batch = ObservationBatch::default();
            assert!(
                assemble_payload(decode(&r), &mut aliases, &fixture.budget, &mut batch).is_none()
            );
            fixture.child.release_retaining_exit().unwrap();
            let until = Instant::now() + Duration::from_secs(2);
            while fixture.child.peek_exit().unwrap().is_none() {
                assert!(Instant::now() < until);
                std::thread::yield_now();
            }
            // The same first-acquisition / mapped-revalidation failure decisions
            // used by reconcile, before the subsequent queued transport drain.
            let gap = if adopted {
                reconcile_retirement_gap(
                    Some(fixture.record.starttime),
                    fixture.record.starttime,
                    || fixture.targets[&pid].process.revalidate_fresh(),
                )
                .unwrap()
            } else {
                objects::acquire_incarnation(&fixture.record)
                    .err()
                    .expect("terminal first acquisition fails")
            };
            assert!(
                identity_failure(gap),
                "host stimulus must reach reconcile's actual retirement branch"
            );
            let mut membership = true;
            let mut code_ranges = usize::from(adopted);
            let (kept, _) = retire_source_owners(
                (&mut fixture.startup, &mut fixture.targets),
                &mut aliases,
                pid,
                Some(&fixture.record),
                gap,
                &mut batch,
                |_, _| {
                    assert!(unsafe { libc::fcntl(file_fd, libc::F_GETFD) } >= 0);
                    assert!(unsafe { libc::fcntl(link_fd, libc::F_GETFD) } >= 0);
                    membership = false;
                    code_ranges = 0;
                    Ok(())
                },
                offload_fd_drop,
                |_| true,
            );
            assert_eq!(
                kept,
                super::RetireOutcome::Retired(true),
                "reconcile erased validated terminal original owner; adopted={adopted}"
            );
            assert!(!membership && code_ranges == 0);
            assert!(
                fixture.targets.is_empty(),
                "terminal reconcile retained mapped relocation authority"
            );
            assert!(
                fixture
                    .startup
                    .get(&pid)
                    .is_some_and(|rows| !rows.is_empty()),
                "retirement dropped terminal owner at {stage} stage"
            );
            assert!(
                aliases.incomplete(),
                "retirement orphaned a pending alias boundary"
            );
            use std::io::Read;
            // N12: link detach runs on the fd-dropper worker; the
            // barrier proves the retire's victim closed (FIFO)
            // before asserting EOF.
            flush_fd_drops();
            assert_eq!(
                fixture.link_peer.read(&mut [0]).unwrap(),
                0,
                "terminal history retained an armed link"
            );
            assert!(unsafe { libc::fcntl(file_fd, libc::F_GETFD) } >= 0);
            let binding = record_binding(&fixture.targets, &fixture.startup, &r)
                .unwrap()
                .unwrap();
            assert!(binding.process.is_none());
            assert!(binding.attachment.historical);
            assert!(
                binding.attachment.site.revalidate_object().is_err(),
                "historical source cannot authorize a new attachment"
            );
            assert_eq!(
                (
                    binding.attachment.cookie,
                    binding.attachment.generation,
                    binding.attachment.object
                ),
                (81, 19, object)
            );
            assert_eq!(binding.starttime, fixture.record.starttime);
            assert_eq!(binding.attachment.site.object_hash(), &hash);
            let mut query = r;
            query.invocation = 8;
            query.kind = c::QUERY;
            let mut begin = query;
            begin.kind = c::ALGORITHM_BEGIN;
            r.kind = c::ALIAS;
            r.algorithm = c::OTHER;
            r.function = c::OTHER;
            r.outcome = 0;
            let mut end = r;
            end.kind = c::ALIAS_END;
            end.function = 1;
            let mut alias8 = r;
            alias8.invocation = 8;
            let mut end8 = end;
            end8.invocation = 8;
            let mut query_results = 0;
            let mut advertisements = 0;
            for queued in [r, end, query, begin, alias8, end8] {
                let binding = record_binding(&fixture.targets, &fixture.startup, &queued)
                    .unwrap()
                    .unwrap();
                assert!(binding.process.is_none());
                assert_eq!(binding.attachment.site.object_hash(), &hash);
                if let Some(payload) =
                    assemble_payload(decode(&queued), &mut aliases, &fixture.budget, &mut batch)
                {
                    match payload {
                        ObservationPayload::QueryResult { .. } => query_results += 1,
                        ObservationPayload::Algorithm { .. } => advertisements += 1,
                        _ => (),
                    }
                }
            }
            assert_eq!((query_results, advertisements), (1, 2));
            assert!(!aliases.incomplete());
            assert!(batch.learned_sites.is_empty());
            assert!(batch.gaps.contains(&ObservationGap::ProcessUnavailable));
            assert!(batch.gaps.contains(&ObservationGap::IntervalUnknown));
            fixture.child.finish_observation().unwrap();
        }
    }
